import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"General Settings","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. System","slug":"_1-system","link":"#_1-system","children":[]},{"level":2,"title":"2. Quick Search Window","slug":"_2-quick-search-window","link":"#_2-quick-search-window","children":[{"level":3,"title":"Search Bar Layout","slug":"search-bar-layout","link":"#search-bar-layout","children":[]},{"level":3,"title":"Result Type Priority & Trigger Characters","slug":"result-type-priority-trigger-characters","link":"#result-type-priority-trigger-characters","children":[]}]},{"level":2,"title":"3. Full Search Window","slug":"_3-full-search-window","link":"#_3-full-search-window","children":[]},{"level":2,"title":"4. Preview Window","slug":"_4-preview-window","link":"#_4-preview-window","children":[]},{"level":2,"title":"5. Quick Navigation","slug":"_5-quick-navigation","link":"#_5-quick-navigation","children":[]},{"level":2,"title":"6. Previews & Thumbnails","slug":"_6-previews-thumbnails","link":"#_6-previews-thumbnails","children":[]}],"relativePath":"user-guide/settings/general.md","filePath":"user-guide/settings/general.md","lastUpdated":1791206033000}`),a={name:`user-guide/settings/general.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="general-settings" tabindex="-1">General Settings <a class="header-anchor" href="#general-settings" aria-label="Permalink to “General Settings”">​</a></h1><p>General Settings covers core application behaviors, search window dimensions and visual layouts, result type priority weights, and preview provider sequences. The page is divided into six top tabs: <strong>System</strong>, <strong>Quick Search Window</strong>, <strong>Full Search Window</strong>, <strong>Preview Window</strong>, <strong>Quick Navigation</strong>, and <strong>Previews &amp; Thumbnails</strong>.</p><h2 id="_1-system" tabindex="-1">1. System <a class="header-anchor" href="#_1-system" aria-label="Permalink to “1. System”">​</a></h2><ul><li><p><strong>Start Lertaro on System Boot</strong>: Automatically launches Lertaro upon Windows user login.</p></li><li><p><strong>Check for Updates on Startup</strong>: Automatically checks online for new releases whenever Lertaro starts.</p></li><li><p><strong>Silent In-Place Updates</strong>: Only available when running as administrator with &quot;Check for Updates&quot; enabled. Downloads and installs updates silently in the background without pop-up interruptions.</p></li><li><p><strong>Enable Hardware Acceleration</strong>: Enabled by default. If your dual-GPU laptop (e.g. NVIDIA Advanced Optimus) fails to switch graphics cards because Lertaro is active, disable this to use software rendering. Requires restarting Lertaro.</p></li><li><p><strong>Hide System Tray Icon</strong>: Hides the icon from the Windows taskbar notification area. The logo inside the Quick Search bar continues to provide the full context menu, so access is never lost.</p></li><li><p><strong>Enable Everything Compatibility Service (IPC)</strong>: Emulates the standard Everything Win32 IPC protocol in the background. Third-party software (such as Directory Opus and Total Commander) can query Lertaro&#39;s in-memory index directly.</p></li><li><p><strong>Enable Fuzzy Matching</strong>: Enabled by default. When active, queries match non-contiguous character sequences. When disabled, queries require contiguous substring matches (see <a href="./../search-syntax.html"><strong>Search Syntax</strong></a>). Takes effect immediately.</p></li><li><p><strong>Keep Search Box Content after Closing</strong>: Disabled by default. When enabled, neither hiding the Quick Window nor pressing <code>Escape</code> in the Full Window empties the box — and <code>Escape</code> in the Full Window closes the window on the first press instead of asking twice. The query a window is handed on its next summon arrives <strong>selected whole</strong>, so the first keystroke replaces it rather than appending. This lasts for the current run only; the text is never written to disk.</p></li><li><p><strong>Show Currently Open Folders in Inline Search</strong>: When the inline window is docked in a file dialog, shows the folders currently open in that dialog when the search query is empty. Enabled by default.</p></li><li><p><strong>Query Token Delimiter</strong>: Single-character text box (default <code>:</code>). Defines the leading character for suffix tokens (e.g. <code>:.pdf</code>, <code>:@doc</code>, <code>:[S]</code>).</p></li><li><p><strong>Log Level</strong>: Dropdown selecting Error / Warning / Info (default) / Debug, controlling log verbosity across all processes.</p></li><li><p><strong>UI Language</strong>: Selects the active display language across the entire application.</p></li><li><p><strong>Settings Item Search Aliases</strong>: Quick search only. An exact alias can match multiple items: add a row for each target. Use the exact display name or item ID. Both system and account environment-variable tasks already include the env keyword.</p></li></ul><h2 id="_2-quick-search-window" tabindex="-1">2. Quick Search Window <a class="header-anchor" href="#_2-quick-search-window" aria-label="Permalink to “2. Quick Search Window”">​</a></h2><p>Fine-tunes the dimensions, layout, and priority rankings of the centered floating search bar:</p><h3 id="search-bar-layout" tabindex="-1">Search Bar Layout <a class="header-anchor" href="#search-bar-layout" aria-label="Permalink to “Search Bar Layout”">​</a></h3><ul><li><strong>Search Bar Width (Pixels)</strong>: Range <code>300–1200px</code>, default <code>570px</code>.</li><li><strong>Search Bar Height (Pixels)</strong>: Range <code>45–120px</code>, default <code>60px</code>. This value proportionally scales result icon sizes, line heights, and typography for visual balance.</li><li><strong>Show Clock in Search Box</strong>: Replaces the placeholder text with current date and time when the search box is empty. The clock disappears as soon as you type.</li><li><strong>Switch to Full Window on Second Hotkey Press</strong>: When enabled, pressing the global summon hotkey while the Quick Window is already open transitions directly into the Full Window, carrying over your active query.</li><li><strong>Lock Position</strong>: Prevents dragging the search bar to avoid accidental displacement.</li><li><strong>Automatically Fill Clipboard Text</strong>: Disabled by default. When the Quick Search Window opens without pre-filled text, new non-empty clipboard text is used as the search query. Manual paste and other windows are unaffected.</li><li><strong>Reset Layout Settings</strong>: Restores all search bar layout properties to initial defaults.</li></ul><h3 id="result-type-priority-trigger-characters" tabindex="-1">Result Type Priority &amp; Trigger Characters <a class="header-anchor" href="#result-type-priority-trigger-characters" aria-label="Permalink to “Result Type Priority &amp; Trigger Characters”">​</a></h3><ul><li><strong>Priority Sorting List</strong>: Drag or move items (Applications, System Settings, Files, Plugin Extensions) to adjust which types rank highest in search results.</li><li><strong>Exclusive Single-Character Trigger</strong>: Assign a dedicated character prefix (e.g. <code>;</code> for File Filters) to restrict searches exclusively to that type when typed at the start of a query.</li></ul><h2 id="_3-full-search-window" tabindex="-1">3. Full Search Window <a class="header-anchor" href="#_3-full-search-window" aria-label="Permalink to “3. Full Search Window”">​</a></h2><p>Configures default window geometry, columns, and sidebars for the main search window (<code>Ctrl+F</code>):</p><ul><li><strong>Window Width / Height (Pixels)</strong>: Width range <code>640–2000px</code> (default <code>854px</code>), height range <code>400–1400px</code> (default <code>480px</code>).</li><li><strong>Single Instance Only</strong>: When enabled, invoking the Full Window focuses the existing instance instead of spawning duplicate windows.</li><li><strong>Close on Hotkey Repeat</strong>: Off by default, so pressing the global hotkey again cycles back to the Quick Search Window carrying the current query. When enabled, pressing it again while the Full Window has focus closes the window outright instead. A visible but unfocused Full Window is brought back to the front either way.</li><li><strong>Reset Search Window Settings</strong>: Reverts default dimensions to factory settings.</li><li><strong>Result Table Column Order</strong>: Customize the display order of columns (Name, Path, Date Modified, etc.) in the tabular view.</li><li><strong>Sidebar Filter Order</strong>: Reorder filter groups in the left sidebar; each category dynamically displays live matching item counts.</li><li><strong>Action Menu Group Order</strong>: Reorder action groups inside the context action menu (<code>Ctrl+O</code>).</li></ul><h2 id="_4-preview-window" tabindex="-1">4. Preview Window <a class="header-anchor" href="#_4-preview-window" aria-label="Permalink to “4. Preview Window”">​</a></h2><ul><li><strong>Preview Window Width / Height (Pixels)</strong>: Width range <code>250–900px</code>, height range <code>250–1200px</code>.</li><li><strong>Reset Preview Settings</strong>: Reverts the QuickLook preview window to standard default proportions, automatically constrained within visible screen bounds.</li></ul><h2 id="_5-quick-navigation" tabindex="-1">5. Quick Navigation <a class="header-anchor" href="#_5-quick-navigation" aria-label="Permalink to “5. Quick Navigation”">​</a></h2><ul><li><strong>Provider Order</strong>: Drag and reorder root categories in the Quick Navigation menu (Favorites, History, Open Folders, and third-party file manager bookmarks).</li></ul><h2 id="_6-previews-thumbnails" tabindex="-1">6. Previews &amp; Thumbnails <a class="header-anchor" href="#_6-previews-thumbnails" aria-label="Permalink to “6. Previews &amp; Thumbnails”">​</a></h2><ul><li><strong>File Preview Provider Order</strong>: Adjust the execution sequence and fallback order for preview renderers (built-in media decoders vs. third-party QuickLook bridge).</li><li><strong>Thumbnail Provider Order</strong>: Adjust the resolution priority for file icon and thumbnail extraction providers.</li></ul>`,19)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};